import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with expanded line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 0,
  });
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const r = createInvoice({
    customerId: ' c-002 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for an unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date formats', () => {
  const testCases = ['2026-10-7', '2026-1-07', '26-10-07', '10-07-2026', 'not-a-date', ''];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  const testCases = ['2026-02-30', '2026-13-01', '2026-00-01', '2026-06-31'];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports NO_LINES for an empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for non-array lines', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  const testCases = [0, -1, 1.5, 'abc', null, undefined];
  for (const qty of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    }), { ok: false, error: 'QTY_INVALID' }, `for qty ${qty}`);
  }
});

test('createInvoice reports UNKNOWN_SKU for a SKU that is not in the catalogue', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 1 }]);
});

test('createInvoice stops at the first error', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 0 }],
  });
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('lineTotal returns qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 50 }), 100);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1 }), 100);
});

test('invoiceTotals calculates subtotal, discount, VAT, and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(85000 * 21 / 100) + Math.round(47500 * 21 / 100));
  assert.equal(totals.total, 85000 + 47500 + totals.vat);
});

test('invoiceTotals handles a single line', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(12345 * 21 / 100));
  assert.equal(totals.total, 12345 + totals.vat);
});

test('invoiceTotals returns zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with a created invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 10 * 8500 + 5 * 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(85000 * 21 / 100) + Math.round(47500 * 21 / 100));
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discountPercent values', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 12.5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice reports DISCOUNT_INVALID for discountPercent outside 0-100', () => {
  const testCases = [-1, 101, 100.1, 'abc', null, undefined];
  for (const discountPercent of testCases) {
    const r = createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent }],
    });
    // undefined should work (defaults to 0), so skip it
    if (discountPercent !== undefined) {
      assert.equal(r.ok, false, `should fail for discountPercent ${discountPercent}`);
      assert.equal(r.error, 'DISCOUNT_INVALID', `for discountPercent ${discountPercent}`);
    }
  }
});

test('createInvoice applies gold tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice uses explicit discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 15 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 15);
});

test('createInvoice uses explicit 0 discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('lineDiscount calculates discount correctly', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 8500);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 10625);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 50 }), 500);
});

test('lineDiscount returns 0 when discountPercent is 0', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100 }), 0);
});

test('invoiceTotals calculates discount correctly with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 8500 + 9500);
  assert.equal(totals.total, 85000 + 47500 - 8500 - 9500);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 85000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals total greater than discount is calculated correctly', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 42500);
});

test('lineVat calculates VAT on amount after discount', () => {
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 }), 2100);
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }), 1890);
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 50, vatRate: 21 }), 1050);
});

test('lineVat handles different VAT rates', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  assert.equal(lineVat({ ...line, vatRate: 0 }), 0);
  assert.equal(lineVat({ ...line, vatRate: 9 }), 9000);
  assert.equal(lineVat({ ...line, vatRate: 21 }), 21000);
});

test('lineVat returns 0 when vatRate is not provided', () => {
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0 }), 0);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 25, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000 + 50000 + 25000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000 + 4500 + 0);
  assert.equal(totals.total, 175000 + 25500);
});

test('invoiceTotals VAT with discount and VAT on same line', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  const amountAfterDiscount = 100000 - 10000;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 100000 - 10000 + expectedVat);
});

test('addLine adds a new line to a draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);
  const invoice = r1.value;

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
